# Check for symmetries
def check_horizontal_symmetry(grid):
    rows = len(grid)
    for r in range(rows):
        cell_forward = grid[r]
        cell_backward = grid[rows-1-r]
        if cell_forward != cell_backward:
            return False
    return True

def check_vertical_symmetry(grid):
    for c in range(len(grid[0])):
        col_forward = [grid[r][c] for r in range(len(grid))]
        col_backward = [grid[r][len(grid[0])-1-c] for r in range(len(grid))]
        if col_forward != col_backward:
            return False
    return True

def check_diagonal_symmetry(grid):
    rows = len(grid)
    # Transpose and reverse main diagonal
    transposed = [[grid[c][r] for c in range(rows)] for r in range(rows)]
    for r in range(rows):
        for c in range(len(grid[r])):
            if transposed[r][c] != grid[r][c]:
                return False
    return True

print(f"Horizontal symmetry: {check_horizontal_symmetry(grid)}")
print(f"Vertical symmetry: {check_vertical_symmetry(grid)}")
print(f"Main diagonal transposition: {check_diagonal_symmetry(grid)}")

# Check if it's palindromic (same when read upside down and reversed)
def is_palindrome_grid(grid):
    rows = len(grid)
    cols = len(grid[0])
    for r in range(rows):
        if grid[r][::-1] != grid[rows-1-r]:
            return False
    return True

